// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../interfaces/stream/artist/IStreamArtistReconstruction.sol";

import "../../interfaces/stream/artist/IStreamArtistArchiveV2.sol";
import "../../libraries/SSTORE2.sol";
import { StreamArtistPayloadStore } from "./StreamArtistPayloadStore.sol";

/// @notice Append-only evidence archive for the proposed artist-authority successor.
/// @dev This contract owns no semantic record or decision. It never authenticates an artist,
///      consumes replay, answers current/latest state, calls a semantic owner, or exposes a
///      mutable binding. Exact evidence must be joined to authoritative owner state elsewhere.
contract StreamArtistArchiveV2 is IStreamArtistArchiveV2, IStreamArtistPayloadArchive {
    bytes32 private constant _MARKER = keccak256("6529STREAM_ARTIST_ARCHIVE_V2");
    bytes32 private constant _BINDING_DOMAIN = keccak256("6529STREAM_ARTIST_ARCHIVE_BINDING_V2");
    uint16 private constant _SCHEMA_VERSION = 2;

    struct EvidenceRecord {
        address pointer;
        uint32 payloadSize;
        uint64 appendedAtBlock;
        bytes32 contentHash;
    }

    address public immutable override artistRegistry;
    address public immutable override operationCoordinator;
    bytes32 public immutable override artistArchiveBindingHashV2;

    mapping(bytes32 evidenceId => mapping(uint64 evidenceVersion => EvidenceRecord)) private
        _evidence;

    constructor(address artistRegistry_, address operationCoordinator_) {
        if (artistRegistry_ == address(0) || operationCoordinator_ == address(0)) {
            revert ArtistArchiveInvalidBinding(artistRegistry_, operationCoordinator_);
        }
        artistRegistry = artistRegistry_;
        operationCoordinator = operationCoordinator_;
        artistArchiveBindingHashV2 = keccak256(
            abi.encode(
                _BINDING_DOMAIN,
                block.chainid,
                artistRegistry_,
                operationCoordinator_,
                type(IStreamArtistArchiveV2).interfaceId,
                _MARKER,
                _SCHEMA_VERSION,
                SSTORE2.MAX_DATA_LENGTH
            )
        );
    }

    function supportsInterface(bytes4 interfaceId) external pure override(IERC165) returns (bool) {
        return interfaceId == type(IStreamArtistArchiveV2).interfaceId
            || interfaceId == type(IStreamArtistPayloadArchive).interfaceId
            || interfaceId == type(IStreamArtistReconstruction).interfaceId
            || interfaceId == type(IERC165).interfaceId;
    }

    function artistArchiveMarkerV2() external pure returns (bytes32) {
        return _MARKER;
    }

    function artistArchiveSchemaV2() external pure returns (uint16) {
        return _SCHEMA_VERSION;
    }

    function artistArchiveMaxEvidenceBytesV2() external pure returns (uint256) {
        return SSTORE2.MAX_DATA_LENGTH;
    }

    function appendArtistEvidenceV2(
        bytes32 evidenceId,
        uint64 evidenceVersion,
        bytes calldata evidence
    ) external returns (bytes32 contentHash, address pointer, bool appended) {
        if (msg.sender != operationCoordinator) {
            revert ArtistArchiveUnauthorizedWriter(msg.sender);
        }
        _requireValidKey(evidenceId, evidenceVersion);
        uint256 payloadSize = evidence.length;
        if (payloadSize == 0) {
            revert ArtistArchiveEmptyEvidence(evidenceId, evidenceVersion);
        }
        if (payloadSize > SSTORE2.MAX_DATA_LENGTH) {
            revert ArtistArchiveEvidenceTooLarge(payloadSize, SSTORE2.MAX_DATA_LENGTH);
        }
        if (block.number > type(uint64).max) {
            revert ArtistArchiveBlockNumberOverflow(block.number);
        }

        contentHash = keccak256(evidence);
        EvidenceRecord storage record = _evidence[evidenceId][evidenceVersion];
        if (record.pointer != address(0)) {
            if (record.contentHash != contentHash || record.payloadSize != payloadSize) {
                revert ArtistArchiveEvidenceConflict(
                    evidenceId, evidenceVersion, record.contentHash, contentHash
                );
            }
            return (record.contentHash, record.pointer, false);
        }

        pointer = SSTORE2.write(evidence);
        record.pointer = pointer;
        // `payloadSize <= SSTORE2.MAX_DATA_LENGTH`, so this narrowing is exact.
        // forge-lint: disable-next-line(unsafe-typecast)
        record.payloadSize = uint32(payloadSize);
        // The explicit bound above makes the frozen uint64 receipt field exact.
        // forge-lint: disable-next-line(unsafe-typecast)
        record.appendedAtBlock = uint64(block.number);
        record.contentHash = contentHash;
        StreamArtistPayloadStore.registerPointer(
            pointer, keccak256("ARTIST_OPERATION_EVIDENCE"), contentHash
        );
        emit ArtistArchiveEvidenceAppendedV2(
            evidenceId, evidenceVersion, contentHash, pointer, payloadSize
        );
        return (contentHash, pointer, true);
    }

    function artistEvidenceMetadataV2(bytes32 evidenceId, uint64 evidenceVersion)
        external
        view
        returns (bytes32 contentHash, address pointer, uint32 payloadSize, uint64 appendedAtBlock)
    {
        _requireValidKey(evidenceId, evidenceVersion);
        EvidenceRecord storage record = _evidence[evidenceId][evidenceVersion];
        if (record.pointer == address(0)) {
            revert ArtistArchiveEvidenceUnavailable(evidenceId, evidenceVersion);
        }
        return (record.contentHash, record.pointer, record.payloadSize, record.appendedAtBlock);
    }

    function artistEvidenceBytesV2(bytes32 evidenceId, uint64 evidenceVersion)
        external
        view
        returns (bytes memory evidence)
    {
        _requireValidKey(evidenceId, evidenceVersion);
        EvidenceRecord storage record = _evidence[evidenceId][evidenceVersion];
        if (record.pointer == address(0)) {
            revert ArtistArchiveEvidenceUnavailable(evidenceId, evidenceVersion);
        }
        evidence = SSTORE2.read(record.pointer);
        bytes32 observedHash = keccak256(evidence);
        if (evidence.length != record.payloadSize || observedHash != record.contentHash) {
            revert ArtistArchiveEvidenceCorrupted(
                evidenceId, evidenceVersion, record.contentHash, observedHash
            );
        }
    }

    function registerArtistStoredPayload(address pointer, bytes32 kind, bytes32 hash)
        external
        override
    {
        if (msg.sender != operationCoordinator) {
            revert ArtistArchiveUnauthorizedWriter(msg.sender);
        }
        StreamArtistPayloadStore.registerPointer(pointer, kind, hash);
    }

    function recordPreimageBytes(bytes32 hash) external view override returns (bytes memory) {
        return StreamArtistPayloadStore.recordBytes(hash);
    }

    function storedPayloadCount() external view override returns (uint256) {
        return StreamArtistPayloadStore.count();
    }

    function storedPayloadAt(uint256 index)
        external
        view
        override
        returns (address, bytes32, bytes32)
    {
        return StreamArtistPayloadStore.at(index);
    }

    function _requireValidKey(bytes32 evidenceId, uint64 evidenceVersion) private pure {
        if (evidenceId == bytes32(0) || evidenceVersion == 0) {
            revert ArtistArchiveInvalidEvidenceKey(evidenceId, evidenceVersion);
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/artist/IStreamArtistEstateOwner.sol";

/// @notice Current-principal classification and explicit estate action capabilities.
/// @dev The fixed self read resolves directly from Identity's local estate records.
library StreamArtistAuthorityPolicy {
    function ordinary(uint8 authorityClass, uint8 status, bool defensive)
        internal
        pure
        returns (bool)
    {
        return (authorityClass == 1 && (status == 1 || status == 2))
            || ((authorityClass == 3 || authorityClass == 4) && status == 3)
            || (defensive
                && status == 4
                && (authorityClass == 1 || authorityClass == 3 || authorityClass == 4));
    }

    function requireOperation(T.Identity memory principal, bytes32 artistId, uint16 operation)
        internal
        view
    {
        bool defensive = operation == 20 || operation == 21 || operation == 27 || operation == 54
            || operation == 44 || operation == 45 || operation == 61;
        if (
            principal.authorityAddress == address(0)
                || !ordinary(principal.authorityClass, principal.status, defensive)
        ) revert T.InvalidIdentity(artistId);
        if (principal.authorityClass == 1) return;
        uint32 required;
        if (operation == 44 || operation == 45 || operation == 47 || operation == 61) {
            required = 16;
        } else if (operation == 12 || operation == 22) {
            required = 8;
        } else if (operation == 14) {
            required = 2;
        } else if (operation == 15) {
            required = 4;
        } else if (operation == 16) {
            required = 1024;
        } else if (operation == 17 || operation == 21 || operation == 52) {
            required = 128;
        } else if (operation == 18 || operation == 25) {
            required = 512;
        } else if (operation == 20) {
            required = 32;
        } else if (operation == 24) {
            required = 1;
        } else if (operation == 28) {
            required = 256;
        } else if (
            operation != 2 && operation != 3 && operation != 7 && operation != 27 && operation != 29
                && operation != 51 && operation != 54
        ) {
            revert T.InvalidIdentity(artistId);
        }
        _requireCapability(principal, artistId, required);
    }

    /// @dev AA-INTENT gives subject7 CAP_INTENT_RECORDS alone; ordinary attestations retain CAP_ATTEST.
    function requireIntentAttestation(T.Identity memory principal, bytes32 artistId) internal view {
        if (
            principal.authorityAddress == address(0)
                || !ordinary(principal.authorityClass, principal.status, false)
        ) revert T.InvalidIdentity(artistId);
        if (principal.authorityClass == 1) return;
        _requireCapability(principal, artistId, 64);
    }

    function _requireCapability(T.Identity memory principal, bytes32 artistId, uint32 required)
        private
        view
    {
        Estate.AuthorityCapabilities memory actual = capabilities(artistId);
        if (
            actual.authorityAddress != principal.authorityAddress
                || actual.authorityClass != principal.authorityClass
                || actual.status != principal.status
                || (actual.effectiveCapabilities & required) != required
        ) {
            revert Estate.EstateCapabilityUnavailable(artistId, required);
        }
    }

    function capabilities(bytes32 artistId)
        internal
        view
        returns (Estate.AuthorityCapabilities memory result)
    {
        bytes memory data =
            abi.encodeCall(IStreamArtistEstateOwner.currentAuthorityCapabilities, (artistId));
        bytes memory raw = new bytes(160);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), address(), add(data, 32), mload(data), add(raw, 32), 160)
            size := returndatasize()
        }
        if (!ok || size != 160) revert T.InvalidIdentity(artistId);
        result = abi.decode(raw, (Estate.AuthorityCapabilities));
        if (result.activationRecordHash == bytes32(0)) revert T.InvalidIdentity(artistId);
    }
}

