    {
        return _royaltyFreezes[keccak256(abi.encode(p, artistId, generation))];
    }

    function authorizeRoyaltyFreeze(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.RoyaltyFreeze calldata p,
