        address signer,
        uint256 nonce
    ) external returns (bytes32 record) {
        _forwardConsentWriter();
    }

    function authorizeContentFreezeWithAuthority(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Content.Freeze calldata p,
        address signer,
        uint256 nonce,
        R.AuthorityFact calldata authority
    ) external returns (bytes32 record) {
        _forwardConsentWriter();
    }

    /// @notice Permanent delegation evidence; the internal mapping retains its original physical slot.
    function recordDelegation(bytes32) external view returns (bytes32) {
        bytes32 recordHash;
        assembly ("memory-safe") { recordHash := calldataload(4) }
        return _recordDelegation[recordHash];
    }

    function _forwardConsentWriter() private {
        address target = consentWriterExtension;
        assembly ("memory-safe") {
            let pointer := mload(0x40)
            calldatacopy(pointer, 0, calldatasize())
            let success := delegatecall(gas(), target, pointer, calldatasize(), 0, 0)
            returndatacopy(pointer, 0, returndatasize())
            if iszero(success) { revert(pointer, returndatasize()) }
            return(pointer, returndatasize())
        }
    }

    function authorityDelegationHydrationState(AH.Query calldata q)
        external
        view
        returns (bytes memory)
    {
        return StreamArtistDelegationCollectionHydration.consentState(
            _policies, _recordDelegation, _saleRecords, _latestSaleConsents, q
        );
    }

    function authorityHydrationState(AH.Query calldata q)
        external
        view
        override
        returns (bytes memory)
    {
        bytes32[] memory records = new bytes32[](q.policies.length);
        for (uint256 j; j < records.length; ++j) {
            records[j] = _policies[
                keccak256(
                    abi.encode(q.collectionId, q.policies[j].phaseId, q.policies[j].policyHash)
                )
            ];
            if (records[j] == 0) revert T.InvalidRecord();
        }
        return abi.encode(records);
    }

    function authorityEconomicsHydrationState(
        AH.Query calldata q,
        T.EconomicsConsent[] calldata terms
    ) external view returns (bytes memory) {
        return StreamArtistEconomicsHydration.exportState(
            _policies,
            _economics,
            _associatedEconomicsRecords,
            _economicsAssociations,
            _recordDelegation,
            q,
            terms
        );
    }

    function authorityReadinessHydrationState(
        AH.Query calldata q,
        T.EconomicsConsent[] calldata economics
    ) external view returns (bytes memory) {
        bytes memory inner =
            StreamArtistEconomicsHydration.exportState(
                _policies,
                _economics,
                _associatedEconomicsRecords,
                _economicsAssociations,
                _recordDelegation,
                q,
                economics
            );
        return StreamArtistContentHydration.exportState(
            _ratifications, _ratificationRecords, _contentConsents, _latestContentConsent, q, inner
        );
    }

    function _hydrateAuthority(AH.Query calldata q, AH.OwnerData calldata p) internal override {
        if (StreamArtistDelegationHydrationCodec.tagged(p.typedState, MD.CONSENT)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistMultipleDelegationCollectionHydration.consents(
                _policies, _recordDelegation, _saleRecords, _latestSaleConsents, p.typedState
            );
            return;
        }
        if (StreamArtistDelegationHydrationCodec.tagged(p.typedState, DH.CONSENT)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistDelegationCollectionHydration.importConsent(
                _policies, _recordDelegation, _saleRecords, _latestSaleConsents, q, p.typedState
            );
            return;
        }
        if (StreamArtistMultipleHydrationCodec.isState(p.typedState)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistMultipleCollectionHydration.policies(_policies, p.typedState);
            return;
        }
        if (StreamArtistContentHydration.isState(p.typedState)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            bytes memory inner = StreamArtistContentHydration.importState(
                _ratifications,
                _ratificationRecords,
                _contentConsents,
                _latestContentConsent,
                q,
                p.typedState
            );
            StreamArtistEconomicsHydration.importState(
                _policies, _economics, _associatedEconomicsRecords, _economicsAssociations, q, inner
            );
            return;
        }
        if (StreamArtistEconomicsHydration.isState(p.typedState)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistEconomicsHydration.importState(
                _policies,
                _economics,
                _associatedEconomicsRecords,
                _economicsAssociations,
                q,
                p.typedState
            );
            return;
        }
        bytes32[] memory records = abi.decode(p.typedState, (bytes32[]));
        if (records.length != q.policies.length || p.nonces.length != 0) revert T.InvalidRecord();
        for (uint256 j; j < records.length; ++j) {
            bytes32 key = keccak256(
                abi.encode(q.collectionId, q.policies[j].phaseId, q.policies[j].policyHash)
            );
            if (_policies[key] != 0 || records[j] == 0) revert T.InvalidRecord();
            _policies[key] = records[j];
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import { StreamArtistConsentTransport } from "./StreamArtistConsentTransport.sol";
import "../../interfaces/stream/artist/IStreamArtistSanctionConfirmation.sol";
import "./StreamArtistConsentStorage.sol";
import "./StreamArtistSanctionConfirmationState.sol";

/// @notice Fixed implementation of the Consent owner's explicit mutations.
/// @dev All semantic callbacks reject direct calls before reading authority or snapshots.
contract StreamArtistConsentWriterExtension is StreamArtistConsentStorage {
    error ExtensionWrongHost(address actual);
    address private immutable _host;

    constructor(
        address host_,
        address registry_,
        address coordinator_,
        address archive_,
        address core_,
        address manager_
    ) StreamArtistConsentStorage(registry_, coordinator_, archive_, core_, manager_) {
        if (host_ == address(0) || host_ == address(this)) revert T.InvalidBinding();
        _host = host_;
    }
    modifier onlyHost() {
        if (address(this) != _host) revert ExtensionWrongHost(address(this));
        _;
    }

    function recordRecoveryApproval(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Recovery.ApprovalRecord calldata r,
        R.AuthorityFact calldata authority,
        Approval.Admission calldata admission
    ) external onlyHost returns (bytes32) {
        _check(c, 22);
        StreamArtistRecoveryApprovalState.Mutation memory m =
            StreamArtistRecoveryApprovalState.recordEncoded(
                _recoveryApprovals,
                _replay,
                StreamArtistRecoveryApprovalState.OwnerContext(
                    _environment(), operationCoordinator, archiveV2, domainId, _revision, _now()
                ),
                msg.data
            );
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, b.artistId, r.terms.collectionId);
        return m.record;
    }

    function consumeSanctionFinalization(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Confirmation.Transition calldata p
    ) external onlyHost returns (bytes32 replayKey) {
        _check(c, 13);
        StreamArtistConsentState.Mutation memory m;
        (m, replayKey) = StreamArtistSanctionConfirmationState.consumeEncoded(
            _sanctions,
            _replay,
            StreamArtistConsentState.Context(
                _environment(), operationCoordinator, archiveV2, domainId, _revision, 0
            ),
            msg.data
        );
        _commit(c, m.action, m.state, m.replay, m.record);
    }

    function recordSanction(
        T.ActionContext calldata c,
        T.Binding calldata b,
        S.Record calldata r,
        R.AuthorityFact calldata authority,
        address finalityRegistry,
        bytes calldata ceremony,
        bytes calldata signature
    ) external onlyHost returns (bytes32) {
        _check(c, 12);
        StreamArtistConsentState.Mutation memory m = StreamArtistSanctionState.recordEncoded(
            _sanctions, _replay, _consentContext(), msg.data
        );
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, b.artistId, r.terms.collectionId);
        return m.record;
    }

    function recordSaleConsent(
        T.ActionContext calldata c,
        T.Binding calldata b,
