        StreamEntropyCollectionConfiguration.configure(
            core,
            collectionEntropyConfig,
            collectionProviderEpoch,
            _revealPolicies,
            collectionId,
            provider,
            collectionSalt,
            publicRequests,
            timeoutBlocks
        );
    }

