        assembly ("memory-safe") { return(add(encoded, 32), mload(encoded)) }
    }

    function configureCollectionRevealPolicy(
        uint256 collectionId,
        uint8 requestMode,
        bytes32 revealOwnerRole,
        uint64 requestSLOBlocks,
        uint256 revealFeePerTokenWei
